 specify:T("Excerpt from spec.md, written by Claude after the interview","Уривок зі spec.md, який Claude пише після інтерв'ю"),
 clarify:T("Questions Claude raised and the analyst's decisions","Питання, які підняв Claude, і рішення аналітика"),
 epic:T("The feature's entry in docs/roadmap.md","Запис фічі в docs/roadmap.md"),
 uxflows:T("Screen inventory and one flow from ux-flows.md","Перелік екранів і один шлях із ux-flows.md"),
 design:T("The surfaces declared in sad.md and the first ADR","Поверхні, оголошені в sad.md, і перший ADR"),
 datamodel:T("The table from data-model.md","Таблиця з data-model.md"),
 api:T("Endpoints from contracts/openapi.yaml with their response codes","Ендпоінти з contracts/openapi.yaml з кодами відповідей"),
 screens:T("One screen from screens.md with all its states","Один екран зі screens.md з усіма станами"),
